// Registra nomes e textos (chave = texto em inglês, para o app trocar só a exibição).
(() => {
  const I = window.I18N, A = window.ABILITIES, P = window.__AB_PT || {};
  for (const [name, v] of Object.entries(P)) {
    I.names[name] = v[0];
    if (A[name] && v[1]) I.text[A[name].text] = v[1];
  }
  delete window.__AB_PT;
})();
